/* Zeste : fiches des ingrédients (origine, conservation, rôle dans un cocktail).
   INFOS[id] = [origine, conservation, rôle en cocktail]. Le degré d'alcool vient de data.js. */
'use strict';

const OPEN_SPIRIT = "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.";
const OPEN_VERMOUTH = "Une fois ouvert, au réfrigérateur et bien bouché : à consommer sous 1 à 3 mois, car il s'oxyde comme un vin.";
const OPEN_JUICE = "Pressé à la minute, c'est le meilleur. Au réfrigérateur : 1 jour au plus, car il perd vite en fraîcheur.";
const OPEN_BUBBLES = "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.";
const OPEN_SYRUP = "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.";
const OPEN_DRY = "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.";
const RAW_EGG = "Œufs très frais, de préférence extra-frais, ou version pasteurisée. Éviter l'œuf cru pour les femmes enceintes, les jeunes enfants et les personnes fragiles.";

const INFOS = {
  /* ----- Spiritueux ----- */
  cognac: ["Eau-de-vie de vin distillée deux fois puis vieillie en fût de chêne, uniquement dans la région de Cognac (Charente, France).", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Apporte rondeur, fruits secs, vanille et boisé. Un VS ou un VSOP suffit pour mélanger ; les plus vieux se gardent pour la dégustation."],
  brandy: ["Eau-de-vie de vin ou de fruit, distillée puis vieillie, produite dans de nombreux pays (France, Espagne, États-Unis, Italie…).", OPEN_SPIRIT, "Remplace le cognac dans les recettes, à moindre coût. Donne de la rondeur et des notes de raisin cuit."],
  armagnac: ["Eau-de-vie de vin du Sud-Ouest de la France (Gascogne), généralement distillée une seule fois, plus rustique que le cognac.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Plus charpenté et fruité que le cognac, qu'il remplace très bien, notamment dans les boissons chaudes et les cocktails de fin de repas."],
  calvados: ["Eau-de-vie de cidre (ou de poiré) de Normandie, vieillie en fût.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Goût de pomme cuite et de boisé. Réchauffe les cocktails d'automne et se marie à la cannelle, au miel, au citron et au gin."],
  pisco: ["Eau-de-vie de raisin du Pérou et du Chili, non vieillie ou très peu.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Floral, fruité et vif, avec un parfum de raisin frais. Excellent dans les sours, avec du citron vert et du blanc d'œuf."],
  kirsch: ["Eau-de-vie de cerises (souvent griottes) distillées avec leurs noyaux, d'Alsace, de Franche-Comté, de Forêt-Noire ou de Suisse. Incolore et sèche, sans sucre ajouté.", OPEN_SPIRIT, "Cerise et noyau, sec et puissant. Le meilleur remplaçant du marasquin : en mettre autant et ajouter un trait de sirop de sucre pour compenser. Un peu suffit aussi à relever un cocktail au gin ou au cognac."],
  grappa: ["Eau-de-vie italienne issue du marc de raisin (peaux et pépins qui restent après le pressage du vin).", OPEN_SPIRIT, "Goût marqué, parfois herbacé. S'emploie avec parcimonie : en rinçage de verre ou en remplacement d'une partie d'un autre spiritueux."],
  gin: ["Spiritueux de céréales aromatisé au genièvre (baies de genévrier) et à d'autres plantes comme la coriandre ou les agrumes. Le style « London dry » est sec, sans sucre ajouté, et se produit dans le monde entier.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Sa fraîcheur de genièvre soutient les agrumes, les amers et les vermouths. Un London dry, sec et classique, convient à presque toutes les recettes."],
  "gin-old-tom": ["Style de gin ancien, légèrement sucré, entre le London dry et le genièvre néerlandais. Redevenu à la mode depuis les années 2010.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Plus rond et légèrement sucré qu'un London dry. Adoucit les cocktails au gin sans sirop supplémentaire."],
  "gin-contemporain": ["Gin dont le genièvre est moins dominant au profit d'autres plantes : fleurs, concombre, agrumes, herbes.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "À choisir selon le cocktail : floral avec un tonic, herbacé pour les cocktails frais. Moins adapté quand la recette demande un genièvre marqué."],
  "rhum-blanc": ["Rhum issu de la mélasse (ou du jus) de canne à sucre, peu ou pas vieilli, souvent filtré. Cuba, Porto Rico, Caraïbes.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Léger et neutre : laisse la place aux agrumes, aux fruits et à la menthe."],
  "rhum-overproof": ["Rhum blanc non réduit, titrant 50 à 75 % vol. (environ 63 % ici), typique de la Jamaïque et des Caraïbes.", OPEN_SPIRIT + " À ce degré, il est inflammable : à tenir éloigné de toute flamme.", "Très puissant et aromatique : s'utilise en petite quantité pour renforcer un cocktail tiki, ou en « float » (fine couche déposée sur le dessus)."],
  aguardiente: ["Eau-de-vie de canne à sucre d'Amérique latine, souvent peu vieillie. Certaines versions sont aromatisées à l'anis.", OPEN_SPIRIT, "Remplace un rhum blanc ou une cachaça, avec un caractère plus brut."],
  "rhum-ambre": ["Rhum vieilli quelques années en fût de chêne, qui lui donne sa couleur dorée.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Plus rond que le blanc, avec vanille, caramel et épices. Va bien dans les punchs et les cocktails tiki."],
  "rhum-vieux": ["Rhum vieilli au moins quelques années en fût (souvent beaucoup plus), très aromatique.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Se déguste volontiers sec. En cocktail, à réserver aux recettes où le rhum s'exprime, avec peu d'ingrédients."],
  "rhum-agricole": ["Rhum issu du jus de canne frais, produit surtout aux Antilles françaises (Martinique, Guadeloupe) ; ici ambré, vieilli en fût.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Notes végétales et épicées, plus sèches que le rhum de mélasse. Se marie avec le citron vert et le sucre de canne."],
  "rhum-agricole-blanc": ["Jus de canne frais fermenté puis distillé, non vieilli. Martinique et Guadeloupe notamment.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Herbacé, vif, plein de caractère. Avec du citron vert et du sucre de canne, ou à la place d'un rhum blanc pour un goût plus végétal."],
  "rhum-brun": ["Rhum jamaïcain de mélasse, à fermentation longue, très riche en arômes (esters) : banane mûre, fruits, goudron.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Une petite dose donne du caractère et de la couleur à un punch ou à un cocktail tiki."],
  "rhum-demerara": ["Rhum du Guyana (région du Demerara), souvent distillé dans des alambics en bois, riche et corsé.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Caramel brûlé, mélasse, épices. Donne de la profondeur aux cocktails tiki et aux cocktails stirred au rhum."],
  cachaca: ["Eau-de-vie de jus de canne frais fermenté, produite au Brésil, non vieillie ou vieillie en fût.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Herbacée, fruitée, un peu végétale. Se marie avec le citron vert écrasé et le sucre."],
  tequila: ["Eau-de-vie d'agave bleu, distillée au Mexique dans des régions définies (Jalisco notamment). La « blanco » n'est pas vieillie.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Vive, poivrée, herbacée. Va très bien avec le citron vert, le pamplemousse et le sel. Choisir une mention « 100 % agave » pour la qualité."],
  "tequila-reposado": ["Tequila vieillie de 2 à 12 mois en fût de chêne, qui l'arrondit et la dore.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Plus ronde que la blanco, avec vanille et épices. Pour des cocktails à l'agave plus doux ou des cocktails d'hiver."],
  mezcal: ["Eau-de-vie d'agave du Mexique (surtout Oaxaca) dont les cœurs sont cuits dans des fours en terre, d'où son goût fumé.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Fumé, terreux, végétal. Quelques millilitres suffisent pour transformer un cocktail à la tequila ou au gin."],
  vodka: ["Eau-de-vie neutre de céréales ou de pommes de terre (Pologne, Russie, Suède, France…), distillée et filtrée plusieurs fois.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Neutre : elle laisse s'exprimer les autres ingrédients. Apporte de la force sans changer le goût."],
  "vodka-citron": ["Vodka aromatisée au citron, par arôme ou par infusion de zestes.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Parfum de zeste sans acidité. Peut être remplacée par une vodka nature plus un zeste de citron."],
  "vodka-vanille": ["Vodka aromatisée à la vanille, par arôme ou par infusion de gousses.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Douceur parfumée qui va bien avec le café, le chocolat et le fruit de la passion."],
  bourbon: ["Whiskey américain composé d'au moins 51 % de maïs, vieilli en fûts de chêne neufs brûlés (Kentucky surtout).", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Doux et vanillé, avec du caramel et des noix. Supporte bien le sucre, les bitters et le citron."],
  rye: ["Whiskey américain composé d'au moins 51 % de seigle, plus sec et épicé que le bourbon.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Poivré et épicé, plus sec que le bourbon. Tient bien face aux liqueurs et aux vermouths."],
  scotch: ["Whisky écossais, mélange de whiskies de malt et de grain vieilli au moins 3 ans.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Équilibré, un peu fumé selon les marques. Bon dans les sours au miel et en highball avec de l'eau gazeuse."],
  "scotch-islay": ["Whisky écossais de l'île d'Islay, dont le malt est séché à la tourbe : goût fumé, iodé, presque médicinal.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Très tourbé. À utiliser en petite quantité, en rinçage du verre ou en fine couche sur le dessus, pour fumer un cocktail."],
  "whiskey-irlandais": ["Whiskey d'Irlande, souvent distillé trois fois, d'où une texture douce et peu tourbée.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Doux et fruité, très facile à mélanger. Va bien avec le café, le miel et les vermouths."],
  absinthe: ["Spiritueux à base d'anis vert, de fenouil et de grande absinthe, développé en Suisse puis en France. Interdite en France de 1915 à 1988.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Très aromatique : quelques gouttes ou un rinçage du verre suffisent. Devient trouble en présence d'eau."],
  pastis: ["Apéritif anisé français, à base d'anis étoilé et de réglisse, né à Marseille en 1932.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Rafraîchissant allongé d'eau très fraîche. En cocktail, apporte l'anis et la réglisse ; s'accorde avec les sirops, le miel, la pomme et les amers."],
  aquavit: ["Eau-de-vie scandinave aromatisée au carvi, avec aneth, fenouil ou anis selon les recettes, parfois vieillie en fût.", "Se garde très longtemps, bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Épicé et herbacé (carvi, aneth). Remplace le gin dans les cocktails secs ou relève les cocktails salés."],

  /* ----- Liqueurs ----- */
  "triple-sec": ["Liqueur d'écorces d'orange amères et douces, d'origine française, titrant de 20 à 40 %.", "Plusieurs années, bouteille bien fermée et à l'abri de la lumière. Son sucre et son alcool (30 à 40 %) la protègent ; seul le parfum d'orange s'estompe avec le temps.", "Parfum d'orange et sucre : équilibre l'acidité du citron dans les sours."],
  cointreau: ["Triple sec français d'Angers (1875), la liqueur d'orange incolore la plus connue.", "Plusieurs années, bouteille fermée, à température ambiante. À 40 %, il ne craint rien ; un dépôt ou un léger trouble au froid est normal et sans gravité.", "Orange vive et nette, moins sucrée que la plupart des triple sec. La référence quand une recette demande une liqueur d'orange."],
  "grand-marnier": ["Liqueur française d'orange amère et de cognac, créée en 1880.", "Très longtemps, comme un cognac : bouteille fermée, debout, à l'abri de la lumière.", "Plus riche et plus boisé grâce au cognac. Remplace un triple sec pour une version plus ronde."],
  curacao: ["Liqueur d'écorces d'orange amère, inspirée de l'île de Curaçao (Antilles néerlandaises) mais produite un peu partout.", "Plusieurs années, bouteille bien fermée et à l'abri de la lumière. Le parfum d'orange s'atténue après quelques années d'ouverture.", "Orangé et doux, un peu plus amer qu'un triple sec, qu'il peut remplacer."],
  "curacao-bleu": ["Curaçao d'orange coloré en bleu, sans différence de goût notable avec le curaçao orange.", "Plusieurs années, à l'abri de la lumière : le soleil fait pâlir sa couleur bleue avant même d'altérer son goût.", "Surtout pour la couleur. Se marie à la vodka, au rhum et aux jus tropicaux."],
  "creme-mure": ["Liqueur de mûres, courante en Bourgogne et en Savoie.", "Une fois ouverte, au réfrigérateur et à consommer dans l'année : peu alcoolisée (environ 15 %), elle perd vite son fruit et peut tourner au brun.", "Sucrée et acidulée, aux baies noires. Se verse souvent en filet sur la fin, pour la couleur."],
  "creme-cassis": ["Liqueur de cassis, spécialité de Dijon (Bourgogne), riche en sucre.", "Une fois ouverte, au réfrigérateur : 6 mois à 1 an. Peu alcoolisée (15 à 20 %), elle s'oxyde, brunit et perd son goût de fruit frais.", "Donne couleur et notes de baies noires. Se marie au vin blanc, aux bulles et au vermouth."],
  "liqueur-framboise": ["Liqueur de framboises. Le Chambord, la plus connue, utilise des framboises noires (Val de Loire).", "Une fois ouverte, au frais et à consommer dans l'année : le goût de fruit frais s'oxyde assez vite.", "Fruitée et sucrée. Va bien avec la vodka, l'ananas et les bulles."],
  "sloe-gin": ["Liqueur anglaise de gin infusé de prunelles (fruit du prunellier) et sucré.", "Plusieurs années bouteille fermée. Ouvert, à consommer dans les 1 à 2 ans, à l'abri de la lumière : le fruit s'atténue peu à peu.", "Acidulé, amandé, rouge rubis. S'emploie comme une liqueur de fruits rouges, souvent avec du citron."],
  marasquin: ["Liqueur de cerises marasques, d'Italie ou de Croatie, incolore et légèrement amère.", "Plusieurs années, bouteille fermée et à l'abri de la lumière. Il s'utilise par petites doses : une bouteille dure longtemps sans souci.", "Cerise et amande amère, peu sucré mais très parfumé. Une petite dose suffit, sinon il domine. À défaut, le kirsch (avec un trait de sirop) est le remplaçant le plus proche ; une liqueur de cerise, plus sucrée et rouge, change la couleur du cocktail."],
  "liqueur-cerise": ["Liqueur de cerises, très variable selon l'origine (Danemark, Alsace, Italie).", "Une fois ouverte, au frais et à l'abri de la lumière : 1 à 2 ans. Son goût de fruit s'atténue avec le temps.", "Cerise et amande, ronde et sucrée. Peut remplacer le marasquin à petite dose, en sucrant un peu plus."],
  "liqueur-abricot": ["Liqueur d'abricots, faite à base de fruits ou d'eau-de-vie d'abricot.", "Une fois ouverte, au frais et à l'abri de la lumière : environ 1 an pour garder son parfum de fruit.", "Fruitée et florale. Adoucit les cocktails au gin ou au calvados."],
  "liqueur-peche": ["Liqueur de pêche, parfois de pêche blanche ou de pêche de vigne.", "Une fois ouverte, au frais et à l'abri de la lumière : environ 1 an pour garder son parfum de fruit.", "Fruitée et sucrée, pour les cocktails d'été. Renforce le goût d'une purée de pêche."],
  "creme-banane": ["Liqueur de banane mûre, d'origine française ou néerlandaise.", "Une fois ouverte, au frais : environ 1 an. Le goût de banane mûre devient peu à peu plus plat.", "Donne la rondeur de la banane mûre aux cocktails crémeux ou tiki."],
  "liqueur-coco": ["Liqueur de noix de coco, souvent à base de rhum.", "Une fois ouverte, à l'abri de la chaleur : 1 à 2 ans. Le froid peut la troubler légèrement, sans conséquence.", "Douce et tropicale : apporte la noix de coco sans la texture de la crème de coco."],
  limoncello: ["Liqueur italienne de zeste de citron (côte amalfitaine, Sorrente), servie très froide.", "Plusieurs années, bouteille bien fermée, à l'abri de la lumière. Au frais pour les liqueurs de fruits et de crème. Se garde au congélateur.", "Citron sucré et parfumé. Sert à la fois de sucre et de citron, très bien avec des bulles."],
  "liqueur-passion": ["Liqueur de fruit de la passion, d'origine française et d'ailleurs.", "Plusieurs années, bouteille bien fermée, à l'abri de la lumière. Au frais pour les liqueurs de fruits et de crème.", "Tropicale et acidulée. Complète une purée de fruit de la passion."],
  chartreuse: ["Liqueur de 130 plantes macérées par les moines chartreux, en Isère, depuis 1737. La verte titre 55 %.", "Pratiquement illimitée : à 55 %, elle continue d'évoluer en bouteille. Debout, à l'abri de la lumière et de la chaleur.", "Puissante, herbacée, mentholée. À doser à la cuillère ; s'accorde bien avec le gin, le citron vert et le marasquin."],
  "chartreuse-jaune": ["Version plus douce et plus sucrée (40 %) de la liqueur des chartreux, au goût de safran et de miel.", "Pratiquement illimitée : à 43 %, elle évolue lentement en bouteille. Debout, à l'abri de la lumière et de la chaleur.", "Plus ronde, miellée et plus douce que la verte. Adoucit un cocktail sec."],
  benedictine: ["Liqueur de 27 plantes et épices de Fécamp (Normandie), au miel et au safran, depuis 1863.", "Plusieurs années, bouteille bien bouchée, debout et à l'abri de la lumière : ses herbes et son miel vieillissent très bien.", "Miel, épices et herbes. Quelques millilitres arrondissent un cocktail au whisky ou au cognac."],
  galliano: ["Liqueur italienne à la vanille et à l'anis étoilé, jaune vif, en bouteille haute.", "Plusieurs années, à l'abri de la lumière : le soleil fait pâlir sa couleur jaune.", "Vanille et anis, couleur jaune vif. Se marie au jus d'orange et aux cocktails crémeux."],
  drambuie: ["Liqueur écossaise de whisky, de miel, d'herbes et d'épices.", "Plusieurs années, comme un whisky : bouteille fermée, debout, à l'abri de la lumière et de la chaleur.", "Liqueur de whisky au miel et aux épices : réchauffe un cocktail au scotch."],
  "creme-menthe": ["Liqueur de menthe poivrée, colorée en vert.", "Plusieurs années, à l'abri de la lumière : la lumière fait pâlir le vert et affadit la menthe.", "Donne une couleur verte et une fraîcheur mentholée, souvent avec du cacao ou de la crème."],
  "creme-menthe-blanche": ["Liqueur de menthe poivrée incolore.", "Plusieurs années, bouteille fermée et à l'abri de la lumière ; la fraîcheur de la menthe s'atténue lentement après ouverture.", "Fraîcheur mentholée sans la couleur verte. Avec du cognac ou de la crème de cacao."],
  "liqueur-sureau": ["Liqueur de fleurs de sureau, la plus connue étant née en Savoie.", "Une fois ouverte, à l'abri de la lumière et idéalement au frais : 1 à 2 ans, le parfum floral étant fragile.", "Florale, entre litchi et poire. Va bien avec le gin, le concombre et les bulles."],
  "creme-violette": ["Liqueur de fleurs de violette, d'Autriche et de France.", "Une fois ouverte, à l'abri de la lumière : 1 à 2 ans. Sa couleur et son parfum floral sont fragiles.", "Florale et violette, surtout pour la couleur. Très peu suffit, sinon le goût devient savonneux."],
  falernum: ["Liqueur-sirop des Caraïbes (Barbade) au citron vert, gingembre, clou de girofle et amande, très peu alcoolisée.", "Peu alcoolisé (environ 11 %) : une fois ouvert, au réfrigérateur et à consommer en quelques mois. Le falernum maison sans alcool se garde 2 à 3 semaines au frais.", "Épicé (girofle, gingembre), citronné et sucré. Typique des cocktails tiki et des cocktails au rhum."],
  campari: ["Apéritif amer italien (Milan, 1860), macération d'herbes, de fruits et d'écorces, d'un rouge profond.", "Plusieurs années, même ouvert, bouteille bien fermée et à l'abri de la lumière ; la couleur rouge pâlit au soleil.", "Amer, orangé, intense. Se marie au vermouth rouge, au gin et à l'eau gazeuse."],
  aperol: ["Apéritif italien à l'orange amère, à la rhubarbe et à la gentiane, né à Padoue en 1919 ; moins fort et moins amer que le Campari.", "Ouvert, à l'abri de la lumière et de la chaleur : environ 1 an. Moins alcoolisé (11 %) que le Campari, il perd plus vite sa fraîcheur d'orange.", "Léger, orangé, entre sucré et amer. Moins amer et moins alcoolisé que le Campari."],
  fernet: ["Amaro italien (Milan, 1845), très amer, à la myrrhe, au safran, à la rhubarbe et à la gentiane.", "Très longtemps, même ouvert : très alcoolisé et amer, il évolue à peine. Bouteille fermée, à l'abri de la lumière.", "Surtout digestif. En cocktail, en très petite quantité : mentholé, amer, puissant."],
  "amaro-nonino": ["Amaro du Frioul (Italie), à base de grappa, de caramel et d'orange amère.", "Plusieurs années, bouteille fermée, à l'abri de la lumière et de la chaleur.", "Amertume douce et caramélisée. Équilibre l'agrume et le bourbon."],
  cynar: ["Amaro italien à l'artichaut et à une douzaine de plantes, plus léger et plus doux que beaucoup d'autres.", "Ouvert, à l'abri de la lumière : 1 à 2 ans, voire plus. Peu alcoolisé (16,5 %), il garde mieux ses arômes au frais.", "Amer végétal, à base d'artichaut. Remplace le Campari pour une amertume plus terreuse."],
  suze: ["Apéritif français à la gentiane jaune (racine), amer et terreux, depuis 1889.", "Ouverte, à l'abri de la lumière : environ 1 an. Peu alcoolisée (15 %), elle s'oxyde lentement : la garder au frais si on la boit rarement.", "Amère et florale, à base de gentiane. Très bien avec du tonic ou en remplacement du Campari pour une version claire."],
  "liqueur-cafe": ["Liqueur de café, par exemple la mexicaine à base de café et de rhum, ou la jamaïcaine.", "Une fois ouverte, à l'abri de la chaleur : 1 à 2 ans. Le café perd en intensité avec le temps.", "Café sucré. Va bien avec la vodka, la crème et l'expresso."],
  "creme-cacao": ["Liqueur de cacao et de vanille, blanche ou brune.", "Plusieurs années, bouteille fermée et à l'abri de la lumière. Un léger dépôt de cacao est possible : agiter avant de servir.", "Chocolat léger. S'accorde avec la crème, la menthe et le cognac."],
  amaretto: ["Liqueur italienne à l'amande, faite avec des noyaux d'abricot ou des amandes amères (Lombardie, Saronno).", "Plusieurs années, bouteille fermée, à température ambiante et à l'abri de la lumière.", "Douceur d'amande. Avec du citron et du blanc d'œuf, ou avec un whisky pour un cocktail de fin de repas."],
  "liqueur-noisette": ["Liqueur de noisette (Piémont, Italie).", "Une fois ouverte, à l'abri de la chaleur : 1 à 2 ans. Les arômes torréfiés s'estompent avec le temps.", "Ronde et torréfiée, avec le café et le chocolat."],
  "creme-whisky": ["Liqueur crémeuse à la crème fraîche et au whiskey, d'origine irlandaise.", "Une fois ouverte, au réfrigérateur et dans les 6 mois : elle contient de la crème. À jeter si elle épaissit ou change d'odeur.", "Onctueuse et sucrée, avec le café et le chocolat. À ne pas mélanger à des jus acides, elle tournerait."],

  /* ----- Vins & vermouths ----- */
  "vermouth-rouge": ["Vin aromatisé et fortifié aux plantes (dont la grande absinthe), né à Turin (Italie) et à Chambéry (France).", "Une fois ouvert, au réfrigérateur et bien bouché : à consommer sous 1 à 3 mois, car il s'oxyde comme un vin.", "Doux-amer et épicé. Arrondit les whiskies, le gin et les amers."],
  "vermouth-sec": ["Vin aromatisé blanc et sec, de France (Marseillan) ou d'Italie.", "Une fois ouvert, au réfrigérateur et bien bouché : à consommer sous 1 à 3 mois, car il s'oxyde comme un vin.", "Sec et herbacé : apporte de la complexité au gin et à la vodka, sans sucrer."],
  "vermouth-blanc": ["Vermouth blanc plus doux, d'Italie (bianco) ou de Chambéry.", "Une fois ouvert, au réfrigérateur et bien bouché : à consommer sous 1 à 3 mois, car il s'oxyde comme un vin.", "Plus doux et floral que le sec. Se boit aussi allongé de tonic."],
  lillet: ["Apéritif de Podensac (Bordeaux) : vins de Bordeaux mêlés à des liqueurs d'agrumes et de quinquina, créé en 1872.", "Une fois ouvert, au réfrigérateur et bien bouché : à consommer sous 1 à 3 mois, car il s'oxyde comme un vin.", "Fruité et délicatement amer. Avec du tonic, ou à la place d'un vermouth blanc."],
  prosecco: ["Vin effervescent italien de Vénétie (cépage Glera), aux bulles légères et fruitées.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Bulles fruitées et légères, moins chères que le champagne en cocktail."],
  champagne: ["Vin effervescent de Champagne (France), à seconde fermentation en bouteille.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Bulles fines et sèches. À verser très frais et en dernier."],
  cremant: ["Vin effervescent français (Alsace, Loire, Bourgogne, Limoux…), fait comme le champagne mais hors de Champagne.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Remplace le champagne à moindre coût, avec la même finesse de bulles."],
  "vin-blanc": ["Vin blanc sec, jeune et acidulé, non boisé (Muscadet, Sauvignon, Picpoul…).", "Une fois ouvert, au réfrigérateur : 3 à 5 jours.", "Acidité et légèreté. Choisir un vin sec et fruité."],
  "vin-rouge": ["Vin rouge jeune, fruité et peu tannique (Beaujolais, côtes-du-rhône, merlot…).", "Une fois ouvert : 3 à 5 jours, bien bouché et au frais.", "Un vin fruité se marie mieux qu'un vin boisé. Pour les boissons chaudes, les punchs et en fine couche sur un sour."],
  porto: ["Vin muté de la vallée du Douro (Portugal), ici tawny : vieilli en fût, aux notes de noix et de caramel.", "Une fois ouvert : 1 à 3 mois au frais, le tawny tient mieux que le ruby.", "Douceur de fruits secs. Se boit aussi allongé de tonic."],
  xeres: ["Vin blanc fortifié d'Andalousie (Jerez, Espagne), sec, vieilli sous voile de levures. Ici fino.", "Très fragile une fois ouvert : au réfrigérateur, à consommer sous 1 à 2 semaines.", "Salin et amandé selon le type (fino, amontillado). Ajoute de la complexité et allège un cocktail."],

  /* ----- Sirops & sucres ----- */
  "sirop-sucre": ["Sucre dissous dans de l'eau à parts égales ; facile à faire à la maison.", "Maison : environ 1 mois au réfrigérateur. Dans le commerce, fermé : plusieurs mois.", "Le sucrant universel du bar : adoucit, équilibre l'acidité et se mélange à froid."],
  "sirop-sucre-riche": ["Deux parts de sucre pour une d'eau : plus épais et plus sucré.", "Environ 1 mois au réfrigérateur, souvent plus car il est très concentré.", "Moins d'eau que le sirop 1:1 : garde la force d'un cocktail et donne une texture plus riche. En mettre environ moitié moins."],
  "sirop-canne": ["Sirop de sucre de canne, parfois non raffiné, courant aux Antilles.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Goût de canne et de mélasse, plus rond que le sirop de sucre. Idéal avec les rhums et le citron vert."],
  "sucre-morceau": ["Sucre de betterave ou de canne en morceaux.", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Se dissout mal à froid : l'écraser avec un trait d'eau ou de bitters au fond du verre."],
  "sucre-blanc": ["Sucre raffiné de betterave (France) ou de canne.", "Indéfiniment, au sec.", "Base des sirops maison, du bord de verre givré, et se dissout dans les liquides chauds."],
  "sucre-roux": ["Sucre de canne partiellement raffiné (cassonade, vergeoise), de couleur brune.", "Indéfiniment, au sec.", "Goût de caramel. À écraser au fond du verre ou à dissoudre dans une boisson chaude."],
  panela: ["Sucre non raffiné de jus de canne cuit et moulé, courant en Amérique latine (piloncillo au Mexique).", "Plusieurs mois, au sec ; il durcit avec le temps.", "Notes de réglisse et de caramel. À dissoudre dans l'eau, chaude ou froide."],
  "sucre-glace": ["Sucre finement broyé, avec un peu d'amidon.", "Plusieurs mois, au sec.", "Se dissout instantanément à froid : cocktails crémeux ou gourmands, ou saupoudré en décor."],
  "sirop-miel": ["Miel dilué dans de l'eau tiède pour devenir liquide (« honey syrup »).", "Environ 1 mois au réfrigérateur.", "Floral et rond. Facile à doser et à mélanger à froid, contrairement au miel pur."],
  miel: ["Produit des abeilles, d'origines florales très variées.", "Indéfiniment, à température ambiante et au sec.", "Doux et floral. Trop épais à froid : le diluer en sirop ou l'utiliser dans une boisson chaude."],
  "sirop-agave": ["Sirop de sève d'agave, issu du Mexique.", "Plusieurs mois, au placard ou au frais.", "Plus sucrant que le sucre et soluble à froid. Accompagne naturellement la tequila et le mezcal."],
  orgeat: ["Sirop d'amandes (à l'origine d'orge), parfumé à la fleur d'oranger.", "Fermé : plusieurs mois. Maison ou ouvert : environ 2 semaines au réfrigérateur ; bien secouer.", "Texture crémeuse, parfum d'amande et de fleur d'oranger. Typique des cocktails tiki."],
  grenadine: ["Sirop à base de jus de grenade, parfois aromatisé artificiellement dans le commerce.", "Fermé : plusieurs mois. Ouvert : 1 à 3 mois au réfrigérateur ; maison : 2 à 4 semaines.", "Couleur rouge et douceur fruitée. Se verse souvent en dernier pour un effet dégradé."],
  "sirop-framboise": ["Sirop de framboises concentré.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Parfum fruité, couleur rose. Pour les limonades, les spritz et les boissons sans alcool."],
  "sirop-cannelle": ["Sirop infusé à la cannelle.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Épicé et chaud. Avec le rhum, le whisky, la pomme et le café."],
  "sirop-gingembre": ["Sirop infusé au gingembre.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Piquant et chaleureux. Remplace une ginger beer avec de l'eau gazeuse, ou réchauffe un sour."],
  "sirop-vanille": ["Sirop infusé à la vanille.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Douceur ronde. Avec le café, le rhum et les fruits tropicaux."],
  "cordial-sureau": ["Sirop de fleurs de sureau, à l'origine un cordial britannique.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Floral, entre litchi et poire. Avec le gin, les bulles ou simplement de l'eau gazeuse."],
  "sirop-camomille": ["Sirop infusé à la camomille.", OPEN_SYRUP, "Floral et un peu miellé. Avec le gin, la pomme ou le miel."],
  "sirop-menthe": ["Sirop de menthe, vert ou incolore.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Menthe sucrée. Remplace les feuilles quand on n'en a pas."],
  "sirop-passion": ["Sirop de fruit de la passion.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Tropical et acidulé. Remplace la purée ou la liqueur de passion."],
  "sirop-curcuma": ["Sirop infusé au curcuma.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Couleur jaune doré, goût terreux et épicé. Pour les cocktails d'hiver."],
  "sirop-rose": ["Sirop de pétales de rose.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Floral et parfumé. À doser avec retenue."],
  "sirop-chocolat": ["Sirop de chocolat ou de cacao.", "Fermé : plusieurs mois. Une fois ouvert, au réfrigérateur : 1 à 2 mois. Un sirop fait maison se garde environ 2 à 4 semaines.", "Pour les cocktails crémeux et les cafés gourmands."],
  "sirop-erable": ["Sève d'érable concentrée, produite surtout au Canada et dans le nord-est des États-Unis.", "Fermé : plusieurs mois. Ouvert : au réfrigérateur, quelques mois.", "Goût de caramel boisé. Remplace le sirop de sucre avec le whisky ou le bourbon."],
  "shrub-framboise": ["Boisson sucrée au vinaigre et au fruit, ancienne méthode de conservation.", "Plusieurs semaines au réfrigérateur : le vinaigre aide à la conservation.", "Acidulé et fruité : remplace le citron et le sucre. Avec de l'eau gazeuse, du gin ou du bourbon."],

  /* ----- Jus & purées ----- */
  citron: ["Jus de citron jaune pressé (Sicile, Espagne, Turquie…).", "Pressé à la minute, c'est le meilleur. Au réfrigérateur : 1 jour au plus, car il perd vite en fraîcheur.", "L'acidité qui équilibre le sucre dans la plupart des sours. Le jus du jour est le plus vif."],
  "citron-vert": ["Jus de citron vert (lime), des Caraïbes, du Mexique ou du Brésil.", "Pressé à la minute, c'est le meilleur. Au réfrigérateur : 1 jour au plus, car il perd vite en fraîcheur.", "Acidité plus aromatique et un peu amère que le citron jaune. Indispensable avec le rhum et la tequila."],
  orange: ["Jus d'orange pressé de préférence (Espagne, Maroc, Floride).", "Pressé : 1 jour au réfrigérateur. En brique ouverte : 3 à 4 jours.", "Doux et acidulé : allonge et adoucit, sans apporter beaucoup d'acidité."],
  pamplemousse: ["Jus de pamplemousse, rose ou blanc.", "Pressé : 1 à 2 jours au réfrigérateur. En brique ouverte : 3 à 5 jours.", "Amer, acidulé et un peu astringent. Se marie à la tequila, au gin et au marasquin."],
  ananas: ["Jus d'ananas, de préférence frais ou pressé à froid.", "Pressé : 1 à 2 jours au réfrigérateur. En brique ouverte : 3 à 5 jours.", "Doux, acidulé, et il fait mousser au shaker. Base des cocktails tropicaux."],
  cranberry: ["Jus de canneberge, baie acide d'Amérique du Nord, généralement sucré.", "Ouvert : 1 à 2 semaines au réfrigérateur.", "Acidité tannique et couleur rouge. Avec la vodka et les agrumes."],
  tomate: ["Jus de tomate, de préférence nature et peu salé.", "Ouvert : 3 à 5 jours au réfrigérateur.", "Salé, acidulé et umami. Base des cocktails salés et épicés."],
  pomme: ["Jus de pomme, pur jus ou trouble.", "Ouvert : 3 à 5 jours au réfrigérateur.", "Doux et fruité. Avec le calvados, le bourbon, la cannelle."],
  grenade: ["Jus de grenade, tannique, acidulé et rouge profond.", "Ouvert : 3 à 5 jours au réfrigérateur.", "Acidulée et fruitée, rouge profond. Base de la grenadine maison et des cocktails d'hiver."],
  "jus-canne": ["Jus pressé de canne à sucre, vert, frais et rare en France.", "À boire tout de suite : il fermente vite. Se congèle.", "Remplace le sirop de sucre, avec un goût herbacé. Avec le rhum agricole ou la cachaça."],
  "puree-peche": ["Purée de pêche blanche, souvent surgelée ou en brique.", "Ouverte : 3 à 5 jours au réfrigérateur ; surgelée : plusieurs mois.", "Veloutée et parfumée, sans sucre ajouté. Se marie aux bulles."],
  mangue: ["Purée de mangue, souvent en brique ou surgelée.", "Ouverte : 3 à 5 jours au réfrigérateur ; surgelée : plusieurs mois.", "Doux, épais et parfumé. Pour les cocktails mixés et les boissons sans alcool."],
  "puree-passion": ["Purée de fruit de la passion, souvent en brique ou surgelée.", "Ouverte : 3 à 5 jours au réfrigérateur ; surgelée : plusieurs mois.", "Acidulée et exotique, très parfumée."],

  /* ----- Fruits & légumes ----- */
  "lime-quartiers": ["Citron vert entier : se presse, se zeste, se coupe en quartiers.", "2 à 3 semaines au réfrigérateur.", "On presse à la demande (jus plus aromatique) ; le zeste est riche en huiles essentielles ; les quartiers s'écrasent au fond du verre ou servent de garniture."],
  "citron-entier": ["Citron jaune entier, de préférence non traité si l'on utilise le zeste.", "2 à 3 semaines au réfrigérateur.", "Jus, zeste et rondelle. Le zeste exprimé au-dessus du verre parfume la surface du cocktail."],
  "orange-entiere": ["Orange entière, de préférence non traitée si l'on utilise le zeste.", "1 à 2 semaines au réfrigérateur.", "Zeste exprimé sur les cocktails amers ou au whisky, rondelle pour décorer, jus pour allonger."],
  "ananas-frais": ["Ananas frais entier ou en morceaux.", "Une fois coupé : 3 à 5 jours au réfrigérateur.", "Jus frais mixé, feuilles et quartier pour la garniture."],
  "peche-blanche": ["Fruit de l'été, à chair blanche, plus parfumée et moins acide que la jaune.", "Mûre : 2 à 3 jours au réfrigérateur ; à garder à température ambiante tant qu'elle n'est pas mûre.", "Mixée en purée pour les cocktails pétillants. Sa recette maison est dans l'onglet Préparations maison."],
  fraise: ["Fraise fraîche, de saison.", "2 à 3 jours au réfrigérateur.", "Douce et colorée. Écrasée au shaker ou mixée ; s'accorde avec le basilic."],
  framboise: ["Framboise fraîche, fruit très fragile.", "1 à 2 jours au réfrigérateur ; se congèle.", "Acidulée et très parfumée. Écrasée au shaker ou mixée."],
  mure: ["Mûre fraîche, sauvage ou cultivée.", "2 à 3 jours au réfrigérateur ; se congèle.", "Sucrée, acidulée et boisée. Écrasée au shaker ou en garniture."],
  concombre: ["Légume frais et aqueux.", "Environ 1 semaine au réfrigérateur.", "Fraîcheur verte. À écraser au shaker ou en rubans dans le verre ; va bien avec le gin."],
  gingembre: ["Rhizome de gingembre frais (Asie, Pérou, Nigéria).", "2 à 3 semaines au réfrigérateur ; se congèle.", "Chaleur piquante. Râpé, pressé ou en sirop."],
  piment: ["Piment frais, rouge ou vert.", "Environ 1 semaine au réfrigérateur.", "Pour relever les cocktails à la tequila ou à la tomate. Très peu suffit ; retirer les graines pour doser."],
  "cerise-marasquin": ["Cerises confites au sirop (type Amarena ou Luxardo).", "Au réfrigérateur, bocal fermé : plusieurs mois.", "Garniture des cocktails au whisky : sucrée et parfumée. Les cerises « maraschino » américaines très rouges sont plus artificielles."],
  olive: ["Olives vertes, dénoyautées ou farcies (Espagne, France).", "Dans leur saumure, au réfrigérateur : plusieurs semaines.", "Garniture des cocktails secs au gin ou à la vodka : le salé équilibre l'alcool. Un trait de saumure donne une version « dirty »."],
  celeri: ["Branche de céleri frais.", "1 à 2 semaines au réfrigérateur.", "Garniture des cocktails salés à la tomate : aromatique et légèrement salée."],
  pasteque: ["Pastèque fraîche, de saison.", "Une fois coupée : 3 à 4 jours au réfrigérateur.", "Jus désaltérant à mixer et filtrer. Se marie au citron vert, à la menthe et à la tequila."],
  raisin: ["Raisin blanc de table.", "1 semaine au réfrigérateur.", "Mixé ou écrasé, ou en garniture."],

  /* ----- Herbes & épices ----- */
  menthe: ["Menthe verte (spearmint), du jardin ou du marché.", "Environ 1 semaine au réfrigérateur, les tiges dans un verre d'eau.", "Fraîcheur aromatique. Claquer les feuilles entre les paumes plutôt que de les écraser, pour éviter l'amertume."],
  basilic: ["Basilic frais, d'Italie ou d'Asie.", "3 à 5 jours : tiges dans l'eau, à température ambiante.", "Parfum herbacé qui va bien avec la fraise, le citron et le gin."],
  romarin: ["Plante aromatique méditerranéenne.", "1 à 2 semaines au réfrigérateur.", "Parfum résineux : infusé dans un sirop ou en garniture, parfois flambé."],
  thym: ["Plante aromatique méditerranéenne.", "1 à 2 semaines au réfrigérateur.", "Herbacé et fin, avec le citron, le gin et le miel."],
  cannelle: ["Écorce de cannelier (Sri Lanka, Chine, Vietnam).", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Épicée et chaude. En bâton pour infuser, en poudre pour saupoudrer."],
  muscade: ["Noix du muscadier (Indonésie, Grenade).", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "À râper au dernier moment sur les cocktails crémeux ou chauds. Parfum chaud et puissant."],
  sel: ["Sel marin ou sel gemme.", "Indéfiniment, au sec.", "Pour givrer le bord du verre. Une pincée relève le citron et le pamplemousse."],
  poivre: ["Baies du poivrier (Inde, Vietnam), de préférence en grains.", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Quelques tours de moulin pour relever les cocktails salés ou à la tequila."],
  "sel-celeri": ["Mélange de sel et de graines de céleri moulues.", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Relève les cocktails salés à la tomate ou à la bière."],
  cardamome: ["Graines d'une plante de la famille du gingembre (Inde, Guatemala).", OPEN_DRY, "Épicée et citronnée : café, gin, sirops."],
  "gousse-vanille": ["Fruit d'une orchidée, cultivée à Madagascar, à Tahiti et au Mexique.", "À l'abri de l'air, de la lumière et de l'humidité : plusieurs mois.", "Pour infuser sirops et spiritueux : parfum rond, chaud et floral. Les graines grattées colorent et parfument."],
  cumin: ["Graines de cumin moulues (Moyen-Orient, Inde).", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Touche terreuse pour des cocktails d'inspiration mexicaine ou épicés."],
  girofle: ["Boutons floraux séchés du giroflier (Madagascar, Indonésie).", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Très puissant : 2 ou 3 suffisent pour parfumer une boisson chaude."],
  curcuma: ["Rhizome séché et moulu (Inde).", OPEN_DRY, "Couleur jaune vif et goût terreux : sirops, cocktails d'hiver."],
  "fleur-d-hibiscus-sechees": ["Fleurs séchées de roselle (Hibiscus sabdariffa), d'Afrique de l'Ouest, du Mexique ou d'Égypte.", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Acidulée, fruitée et rouge profond. À infuser à chaud ou à froid."],

  /* ----- Bitters ----- */
  angostura: ["Bitters aromatiques créés en 1824 à Angostura (Venezuela), aujourd'hui produits à Trinité-et-Tobago, à la recette secrète à base de gentiane.", "Plusieurs années, bouchon fermé, au placard.", "Quelques gouttes pour structurer un cocktail : relèvent les épices et l'amertume, surtout avec le whisky et le rhum."],
  peychaud: ["Bitters de La Nouvelle-Orléans (années 1830), à la gentiane et à l'anis.", "Plusieurs années, bouchon fermé, au placard.", "Plus floral et anisé que l'Angostura, avec une couleur rouge. Typique des cocktails de La Nouvelle-Orléans."],
  "orange-bitters": ["Bitters à l'écorce d'orange amère.", "Plusieurs années, bouchon fermé, au placard.", "Fraîcheur d'agrumes. Avec le gin, le vermouth et le whisky."],
  "bitters-chocolat": ["Bitters au cacao grillé et aux épices.", "Plusieurs années, bouchon fermé, au placard.", "Notes de cacao, avec le whisky, le rhum et le café."],
  "bitters-sans-alcool": ["Version sans alcool des amers aromatiques (base de glycérine).", "Fermé : plusieurs mois ; ouvert : quelques mois, au frais.", "Pour les mocktails : apportent structure et amertume sans alcool."],

  /* ----- Softs & eaux ----- */
  "eau-gazeuse": ["Eau pétillante, naturelle ou gazéifiée.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Allonge sans sucrer. Verser doucement pour garder les bulles."],
  eau: ["Eau du robinet ou en bouteille.", "À puiser au moment.", "Dilue, adoucit et lie un cocktail. La glace qui fond fait partie de la recette."],
  tonic: ["Eau gazeuse sucrée à la quinine (écorce de quinquina, d'Amérique du Sud).", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Amer et sucré. Allonge le gin, la vodka et les amers."],
  "ginger-beer": ["Boisson gazeuse au gingembre, d'origine britannique, plus piquante que le ginger ale.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Piquante et corsée. Allonge la vodka, le rhum et le whisky."],
  "ginger-ale": ["Soda léger au gingembre, d'origine irlandaise.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Plus douce que la ginger beer. Allonge le whisky et le cognac."],
  cola: ["Soda au cola, doux, épicé et caramélisé.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Allonge les rhums et les whiskies."],
  limonade: ["Soda ou boisson au citron.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Allonge avec une acidité douce, pour les cocktails d'été."],
  "soda-pamplemousse": ["Soda au pamplemousse rose.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Amer et acidulé. Allonge la tequila avec du citron vert."],
  citronnade: ["Boisson de citron pressé, d'eau et de sucre.", "Maison : 2 à 3 jours au réfrigérateur.", "Fraîche et acidulée : allonge un gin, une vodka ou un rhum blanc."],
  "soda-coco": ["Soda à la noix de coco.", "Une fois ouverte, la bouteille perd ses bulles en 1 à 2 jours : l'ouvrir au dernier moment et la garder fraîche.", "Allonge les cocktails tropicaux avec du rhum."],

  /* ----- Épicerie ----- */
  "blanc-oeuf": ["Œufs frais, ou blanc d'œuf pasteurisé en bouteille.", "Œufs très frais, de préférence extra-frais, ou version pasteurisée. Éviter l'œuf cru pour les femmes enceintes, les jeunes enfants et les personnes fragiles. Séparé : 2 à 3 jours au réfrigérateur.", "Fait mousser et donne une texture soyeuse et une mousse blanche stable, sans goût marqué. Shaker d'abord sans glace (« dry shake »), puis avec glace."],
  aquafaba: ["Eau de cuisson ou de conserve des pois chiches.", "Ouvert : 3 à 5 jours au réfrigérateur ; se congèle.", "Remplace le blanc d'œuf (environ 30 ml pour un blanc), pour une version végane. Mousse un peu moins ferme et léger goût végétal."],
  "jaune-oeuf": ["Œufs frais, de préférence extra-frais.", "Œufs très frais, de préférence extra-frais, ou version pasteurisée. Éviter l'œuf cru pour les femmes enceintes, les jeunes enfants et les personnes fragiles. Séparé : 1 à 2 jours au réfrigérateur.", "Apporte richesse, onctuosité, couleur et goût plein. Il ne mousse pas comme le blanc : à fouetter avec du sucre."],
  oeuf: ["Œuf de poule, frais ou extra-frais.", "Œufs très frais, de préférence extra-frais, ou version pasteurisée. Éviter l'œuf cru pour les femmes enceintes, les jeunes enfants et les personnes fragiles. 3 à 4 semaines au réfrigérateur, entier.", "Entier, il donne à la fois une texture crémeuse (jaune) et de la mousse (blanc)."],
  "creme-liquide": ["Crème de lait liquide, entière ou fleurette (30 à 35 % de matière grasse).", "Au réfrigérateur : 3 à 5 jours une fois ouverte.", "Velours et douceur. Fouettée légèrement, elle flotte sur un café."],
  lait: ["Lait de vache, entier de préférence.", "Au réfrigérateur : 3 jours une fois ouvert (frais).", "Allonge et adoucit. Ne pas le mélanger à un jus acide, il caillerait."],
  "lait-amande": ["Boisson végétale à l'amande.", "Ouverte : 5 à 7 jours au réfrigérateur.", "Alternative végétale au lait : douceur et goût de noisette léger."],
  "lait-coco": ["Lait de noix de coco (Thaïlande, Philippines).", "Ouvert : 3 à 4 jours au réfrigérateur ; bien secouer avant emploi.", "Onctueux et tropical, moins sucré que la crème de coco."],
  "creme-coco": ["Crème de coco sucrée (type « cream of coconut »).", "Ouverte : environ 1 semaine au réfrigérateur ; bien secouer avant emploi.", "Très sucrée et épaisse. Ne pas confondre avec la crème de coco non sucrée ni le lait de coco."],
  expresso: ["Café moulu extrait sous pression en 25 à 30 secondes.", "À préparer au moment : il s'oxyde vite et devient amer après une heure.", "Amertume, parfum et mousse (crema). À utiliser froid pour bien mousser au shaker."],
  cafe: ["Café filtré ou de cafetière.", "À préparer au moment.", "Chaud et corsé, avec le whisky, le rhum ou les liqueurs crémeuses."],
  worcestershire: ["Sauce anglaise fermentée (anchois, tamarin, oignon, vinaigre), née à Worcester en 1837.", "Plusieurs années, au placard.", "Salée, acidulée et umami, pour les cocktails salés. Quelques gouttes suffisent."],
  tabasco: ["Sauce piquante au piment tabasco, au vinaigre et au sel (Louisiane, 1868).", "Plusieurs années, au placard.", "Piquant, pour les cocktails salés. Quelques gouttes."],
  raifort: ["Racine de raifort râpée, en sauce.", "Après ouverture : au réfrigérateur, quelques semaines.", "Piquant vif pour les cocktails à la tomate. Une pointe suffit."],
  vanille: ["Gousses de vanille macérées dans l'alcool (Madagascar, Tahiti).", "Plusieurs années, au placard.", "Parfum rond : cocktails crémeux, milkshakes. Très peu suffit. L'extrait contient lui-même un peu d'alcool."],
  "fleur-oranger": ["Eau distillée de fleurs d'oranger amer (Maroc, Tunisie, Provence).", "Plusieurs mois au placard, environ 1 an une fois ouverte.", "Parfum très puissant : quelques gouttes suffisent, surtout avec la crème ou l'amande."],
  "the-noir": ["Feuilles de Camellia sinensis, fermentées (Chine, Inde, Sri Lanka).", "Infusé : 1 jour au réfrigérateur.", "Tannique et boisé. Pour les punchs et les boissons allongées."],
  "the-vert": ["Feuilles de Camellia sinensis non fermentées (Chine, Japon).", "Infusé : 1 jour au réfrigérateur.", "Végétal et frais. Infuser à 70-80 °C pour éviter l'amertume."],
  "infusion-hibiscus": ["Fleurs d'hibiscus infusées dans l'eau chaude.", "Au réfrigérateur : 3 à 4 jours.", "Rouge, acidulée et fruitée, pour les boissons sans alcool."],
  "cold-brew": ["Café infusé à froid pendant 12 à 18 heures, peu acide.", "Au réfrigérateur : 5 à 7 jours.", "Café plus doux et moins amer que l'expresso, à utiliser froid."],
  "cafe-soluble": ["Café lyophilisé en poudre ou granulés.", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "À dissoudre dans un peu d'eau chaude, pour les cocktails crémeux ou les cafés fouettés."],
  "lait-riz": ["Boisson végétale de riz.", "Ouverte : 5 à 7 jours au réfrigérateur.", "Alternative végétale au lait, plus neutre."],
  "lait-concentre": ["Lait réduit et sucré, en boîte ou en tube.", "Ouvert : environ 1 semaine au réfrigérateur.", "Sucré et onctueux, avec le café ou les liqueurs crémeuses."],
  yaourt: ["Yaourt nature, de vache ou végétal.", "Au réfrigérateur : 3 à 5 jours après ouverture.", "Acidulé et crémeux, pour des boissons mixées type lassi."],
  "vinaigre-cidre": ["Vinaigre de cidre de pomme.", "Plusieurs années, au placard.", "Pour les shrubs : acidité douce et fruitée."],
  "vinaigre-blanc": ["Vinaigre de vin blanc.", "Plusieurs années, au placard.", "Pour les shrubs : acidité nette."],
  tamarin: ["Pulpe du fruit du tamarinier (Afrique, Asie), en pâte.", "Plusieurs mois, au réfrigérateur.", "Aigre-doux et fruité, à diluer dans l'eau ou à shaker avec la tequila."],
  "concentre-de-tamarin": ["Concentré de pulpe de tamarin, prêt à doser.", "Ouvert : plusieurs mois au réfrigérateur.", "Aigre-doux, plus facile à doser que la pâte."],
  chia: ["Graines de Salvia hispanica (Mexique).", "Au sec et à l'abri de la lumière, plusieurs mois, voire plusieurs années.", "Texture gélifiée une fois hydratées 10 à 15 minutes, pour les boissons rafraîchissantes."],
  marmelade: ["Confiture d'agrumes amers (oranges de Séville), d'origine britannique.", "Ouverte : au réfrigérateur, plusieurs semaines.", "Acidulée, amère et texturée : remplace le sirop dans un cocktail au gin."],
  chocolat: ["Chocolat noir (70 % de cacao ou plus), de préférence de couverture.", "Plusieurs mois, au frais et au sec.", "Fondu pour des boissons chaudes ou râpé en garniture."],
  matcha: ["Poudre de thé vert japonais (Uji, Kyoto).", "Au réfrigérateur, bien fermé : quelques mois.", "À fouetter dans un peu d'eau tiède : mousse verte et amertume végétale."],
  "yerba-mate": ["Feuilles de Ilex paraguariensis (Argentine, Paraguay, Brésil).", "Infusée : 1 jour au réfrigérateur.", "Tannique et herbacée, pour des boissons allongées rafraîchissantes."],
  amandes: ["Amandes émondées (sans la peau) ou en poudre, d'Espagne, d'Italie ou de Californie.", "Au sec et à l'abri de la lumière : plusieurs mois ; la poudre rancit plus vite.", "Base de l'orgeat maison et des laits d'amande ; goût doux et gras."]
};

